{
  "question_restated": "Why did airport pickups (JFK, LaGuardia) differ between Sunday 2024-07-28 and Tuesday 2024-07-30?",
  "metric": "airport_trips (trips where pickup_zone or dropoff_zone is JFK Airport, LaGuardia Airport, or Newark Airport) and total_valid_trips per day, with hourly normalization if coverage differs",
  "focus": "Sunday 2024-07-28 vs Tuesday 2024-07-30, both fully 24-hour covered, July 2024 context",
  "baseline": "Tuesday 2024-07-30 as the dry comparator; profiler-verified baseline: 75768 valid trips on 2024-07-28 vs 94765 on 2024-07-30 (-20.0%)",
  "hypotheses": [
    {
      "id": "H1",
      "claim": "Sunday has intrinsically lower airport‑trip share than Tuesday due to reduced business travel and fewer commuter flights, independent of weather.",
      "test": "SELECT pickup_date, SUM(CASE WHEN pickup_zone IN ('JFK Airport','LaGuardia Airport','Newark Airport') OR dropoff_zone IN ('JFK Airport','LaGuardia Airport','Newark Airport') THEN 1 ELSE 0 END) AS airport_trips, COUNT(*) AS total_trips FROM investigator.trips WHERE pickup_date IN ('2024-07-28','2024-07-30') AND is_valid_trip GROUP BY pickup_date"
    },
    {
      "id": "H2",
      "claim": "Weather on Sunday 2024-07-28 (higher precip_mm or non‑zero rain_mm) suppressed airport‑trip demand relative to the dry Tuesday 2024-07-30.",
      "test": "SELECT w.day, w.precip_mm, w.rain_mm, w.wmo_code, SUM(CASE WHEN pickup_zone IN ('JFK Airport','LaGuardia Airport','Newark Airport') OR dropoff_zone IN ('JFK Airport','LaGuardia Airport','Newark Airport') THEN 1 ELSE 0 END) AS airport_trips, COUNT(*) AS total_trips FROM investigator.nyc_daily_weather w LEFT JOIN investigator.trips t ON t.pickup_date = w.day AND t.is_valid_trip WHERE w.day IN ('2024-07-28','2024-07-30') GROUP BY w.day, w.precip_mm, w.rain_mm, w.wmo_code"
    },
    {
      "id": "H3",
      "claim": "The zone‑level distribution of trips changed between Sunday and Tuesday, with fewer trips to/from airport zones on Sunday even after normalizing for total volume.",
      "test": "SELECT pickup_date, pickup_zone, dropoff_zone, COUNT(*) AS trips FROM investigator.trips WHERE pickup_date IN ('2024-07-28','2024-07-30') AND is_valid_trip AND (pickup_zone IN ('JFK Airport','LaGuardia Airport','Newark Airport') OR dropoff_zone IN ('JFK Airport','LaGuardia Airport','Newark Airport')) GROUP BY pickup_date, pickup_zone, dropoff_zone ORDER BY pickup_date, trips DESC FETCH FIRST 200 ROWS ONLY"
    }
  ],
  "memory_used": []
}

